from bank_common import *

FOOD=[('pain','m'),('salade','f'),('eau','f'),('riz','m'),('soupe','f'),('huile','f'),('fromage','m'),('viande','f'),('ail','m'),('lait','m'),('farine','f'),('avoine','f'),('beurre','m'),('confiture','f'),('ananas','m'),('sucre','m'),('crème','f'),('orge','f'),('sel','m'),('semoule','f'),('épinards','p'),('poisson','m'),('compote','f'),('endives','p'),('chocolat','m'),('purée','f'),('amandes','p'),('café','m'),('sauce','f'),('eau gazeuse','f'),('thé','m'),('moutarde','f'),('abricots secs','p'),('miel','m'),('mayonnaise','f'),('oranges','p'),('yaourt','m'),('polenta','f'),('olives','p'),('jus de pomme','m'),('cannelle','f'),('haricots','p'),('couscous','m'),('levure','f'),('œufs','p'),('persil','m'),('vanille','f'),('échalotes','p'),('boulgour','m'),('coriandre','f')]
rows=[];quantity=[];indef=[];contractions=[]
for i,(noun,g) in enumerate(FOOD):
 a='des' if g=='p' else 'de l’' if vowel(noun) and noun!='haricots' else 'du' if g=='m' else 'de la'
 rows.append(item('Pour le repas, je prends ___ '+noun+'.',a,['du','de la','de l’','des']))
 negative=i%2==0;answer='d’' if vowel(noun) and noun!='haricots' else 'de'
 if negative:prompt='Je ne prends pas ___ '+noun+' aujourd’hui.'
 else:prompt='La recette demande un peu ___ '+noun+'.'
 quantity.append(item(prompt,answer,[answer,a,'des' if a!='des' else 'du']))
 noun2,plur,g2=NOUNS[i];mode=i%5
 if mode==0:prompt=f'Je vérifie ___ {noun2} du dossier (un par un).';ans='chaque'
 elif mode==1:prompt=f'Je ne garde ___ {noun2} inutile (quantité nulle).';ans='aucun' if g2=='m' else 'aucune'
 elif mode==2:prompt=f'Je compare ___ {plur} (plus d’un, nombre non précisé).';ans='plusieurs'
 elif mode==3:prompt=f'Je range ___ les {plur} sans exception.';ans='tous' if g2=='m' else 'toutes'
 else:prompt=f'Je laisse ___ {plur} de côté (un petit nombre).';ans='quelques'
 indef.append(item(prompt,ans,[ans,'chaque' if ans!='chaque' else 'plusieurs','toute' if g2=='m' else 'tout']))
 if i%2:
  answer=a;prompt='Pour cuisiner, nous utilisons ___ '+noun+'.'
 else:
  n,pl,g2=NOUNS[i];answer='du' if g2=='m' and not vowel(n) else 'de la' if g2=='f' and not vowel(n) else 'de l’'
  prompt='Je parle ___ '+n+' que vous avez choisi'+('e' if g2=='f' else '')+'.'
 contractions.append(item(prompt,answer,[answer,'de le','de les']))
add('g3','Choisir un partitif','Complétez avec du, de la, de l’ ou des selon l’aliment.',rows)
add('g4','Exprimer une quantité','Complétez avec de ou d’ après la quantité ou la négation.',quantity)
add('g5','Préciser une quantité indéfinie','Complétez selon le sens indiqué.',indef)
add('g6','Partitif ou article contracté','Complétez le groupe nominal avec la forme correcte de de et de l’article.',contractions)

