rows={k:[] for k in ['k2','k3','k4','k5','k6','k7','k11']}
for i,(effect,cause) in enumerate(CAUSE):
 # Syntax is intentionally kept stable; the fifty situations vary in meaning.
 rows['k3'].append(item(f'{effect} ___ {cause} (cause).','parce que',['parce que','pour que','bien que']))
